CREATE SCHEMA IF NOT EXISTS racing;
REVOKE ALL ON SCHEMA racing FROM PUBLIC;
CREATE TABLE IF NOT EXISTS racing.inventory (id integer PRIMARY KEY CHECK(id=1), body text NOT NULL);
INSERT INTO racing.inventory VALUES(1,'{"schemaVersion":1,"revision":0,"parts":[],"requests":[],"orders":[],"events":[],"alerts":[]}') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS racing.commands (id text PRIMARY KEY, action text NOT NULL, provenance text, actor text);
CREATE TABLE IF NOT EXISTS racing.delivery_cache (id text PRIMARY KEY, body text NOT NULL);
CREATE TABLE IF NOT EXISTS racing.part_media (id text PRIMARY KEY, mime text NOT NULL, bytes bytea NOT NULL, width integer NOT NULL, height integer NOT NULL, source_hash text NOT NULL);
CREATE TABLE IF NOT EXISTS racing.order_import_sessions (id text PRIMARY KEY, body text NOT NULL);
CREATE TABLE IF NOT EXISTS racing.order_import_receipts (source_hash text PRIMARY KEY, import_id text UNIQUE NOT NULL, identity text, command_id text NOT NULL, created_at bigint NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS order_import_identity ON racing.order_import_receipts(identity) WHERE identity IS NOT NULL;
CREATE TABLE IF NOT EXISTS racing.notification_settings (id integer PRIMARY KEY CHECK(id=1), body text NOT NULL);
INSERT INTO racing.notification_settings VALUES(1,'{"revision":0,"enabled":false,"recipient":"","reminderHours":24,"dashboardUrl":""}') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS racing.notification_outbox (id text PRIMARY KEY, body text NOT NULL, seq bigserial);
CREATE TABLE IF NOT EXISTS racing.notification_episodes (id text PRIMARY KEY, body text NOT NULL);
CREATE TABLE IF NOT EXISTS racing.notification_commands (id text PRIMARY KEY, action text NOT NULL);
CREATE TABLE IF NOT EXISTS racing.members (id text PRIMARY KEY, email text NOT NULL, role text NOT NULL CHECK(role IN ('member','buyer','admin')), status text NOT NULL CHECK(status IN ('pending','approved','revoked')), revision integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS racing.control (id integer PRIMARY KEY CHECK(id=1), bootstrapped boolean NOT NULL DEFAULT false);
INSERT INTO racing.control VALUES(1,false) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS racing.audit (id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS racing.uploads (id text PRIMARY KEY, owner text NOT NULL, purpose text NOT NULL, object_key text NOT NULL UNIQUE, mime text NOT NULL, size integer NOT NULL, created_at bigint NOT NULL);
ALTER TABLE racing.uploads ADD COLUMN IF NOT EXISTS completed boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS racing.jobs (id text PRIMARY KEY, token text, lease_until bigint NOT NULL DEFAULT 0, last_success bigint, last_error text);
CREATE TABLE IF NOT EXISTS racing.tracking_requests (order_id text PRIMARY KEY, requested_at bigint NOT NULL);
REVOKE ALL ON ALL TABLES IN SCHEMA racing FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA racing FROM PUBLIC;
